WITH q AS (SELECT v.vehicle_id,v.make,v.model,v.year,c.category_name,v.seating_capacity,v.fuel_type,v.color,v.status,(SELECT r.rate_amount FROM public.rental_rate r WHERE r.category_id=v.category_id AND r.rental_period_type='Daily' AND r.rate_status='Active' ORDER BY r.rate_id LIMIT 1)+v.unit_rate_adjustment AS daily_rate FROM public.vehicle v JOIN public.vehicle_category c ON c.category_id=v.category_id WHERE c.category_status='Active' AND v.status<>'Retired' ORDER BY c.category_name,v.make,v.model) SELECT jsonb_build_object('rows',count(*),'md5',md5(COALESCE(string_agg(to_jsonb(q)::text,E'\n' ORDER BY to_jsonb(q)::text),''))) FROM q;
